((root,factory)=>{const api=factory(typeof module==='object'&&module.exports?require('./pertidaksamaan-majemuk-core.js'):root.CompoundLesson);if(typeof module==='object'&&module.exports)module.exports=api;else root.GraphReading=api;})(typeof window==='undefined'?globalThis:window,intervals=>{
'use strict';
const graphs=[{id:'mixed',nodes:[[-4,-1],[-2,3],[0,1],[2,1],[4,-1]],lc:true,hc:true,domain:'[-4,4]',range:'[-1,3]',behavior:'Naik pada interval dari negatif empat sampai negatif dua; turun dari negatif dua sampai nol; konstan dari nol sampai dua; lalu turun dari dua sampai empat.',extrema:'Maksimum tiga dicapai pada masukan negatif dua. Minimum negatif satu dicapai pada kedua ujung, yaitu negatif empat dan empat.'},{id:'open',nodes:[[-2,-1],[2,3]],lc:false,hc:false,domain:'(-2,2)',range:'(-1,3)',behavior:'Naik pada seluruh domain, yaitu interval terbuka dari negatif dua sampai dua.',extrema:'Tidak ada maksimum maupun minimum. Keluaran dapat mendekati tiga dan negatif satu, tetapi tidak mencapai keduanya. Masih ada keluaran yang lebih besar atau lebih kecil daripada setiap keluaran yang dicapai.'},{id:'constant',nodes:[[-4,1],[4,1]],lc:true,hc:true,domain:'[-4,4]',range:'\\{1\\}',behavior:'Konstan pada seluruh domain. Tidak naik atau turun secara ketat.',extrema:'Nilai maksimum dan minimum sama-sama satu, dicapai oleh semua masukan pada domain.'}];
function inDomain(g,x){const lo=g.nodes[0][0],hi=g.nodes[g.nodes.length-1][0];return (x>lo||(g.lc&&x===lo))&&(x<hi||(g.hc&&x===hi));}
function value(g,x){if(!inDomain(g,x))return null;for(let i=1;i<g.nodes.length;i++){const [ax,ay]=g.nodes[i-1],[bx,by]=g.nodes[i];if(x>=ax&&x<=bx)return ay+(by-ay)*(x-ax)/(bx-ax);}return null;}
function preimage(g,k){const found=[];for(let i=1;i<g.nodes.length;i++){const [ax,ay]=g.nodes[i-1],[bx,by]=g.nodes[i];if(ay===by){if(k===ay)found.push({lo:ax,hi:bx,lc:inDomain(g,ax),hc:inDomain(g,bx)});}else if(k>=Math.min(ay,by)&&k<=Math.max(ay,by)){const x=ax+(k-ay)*(bx-ax)/(by-ay);if(inDomain(g,x))found.push({lo:x,hi:x,lc:true,hc:true});}}
const sorted=found.sort((a,b)=>a.lo-b.lo||Number(b.lc)-Number(a.lc)),merged=[];for(const i of sorted){const last=merged[merged.length-1];if(last&&(i.lo<last.hi||(i.lo===last.hi&&(last.hc||i.lc)))){if(i.hi>last.hi){last.hi=i.hi;last.hc=i.hc;}else if(i.hi===last.hi)last.hc=last.hc||i.hc;}else merged.push({...i});}return merged;}
const screen=(x,y)=>({x:250+x*40,y:240-y*40});
return {graphs,inDomain,value,preimage,screen,contains:intervals.contains,intervalTex:intervals.intervalTex};
});
